from pathlib import Path
from html import escape
root=Path('/workspace/sites/gfa/dist')
nav=[('fashion-house','Fashion house'),('gallery','Our work'),('academy','Academy'),('courses','Training'),('about','About')]
def photo(which,cls='',alt='Graceyy fashion work'):
    coords={'gold':(533,812,145,194),'pink':(70,1227,145,192),'bride':(222,1227,145,192),'fit':(378,1018,145,194),'students':(222,602,145,191),'corset':(378,602,145,191),'training':(533,393,145,191),'black':(533,1227,145,192),'goldmodel':(378,812,145,194)}
    x,y,w,h=coords[which]
    return f'<div role="img" aria-label="{alt}" class="photo {cls}" style="--sx:{691/w*100}%;--sy:{1536/h*100}%;--px:{x/(691-w)*100}%;--py:{y/(1536-h)*100}%"></div>'
def btn(text,url,outline=False):return f'<a class="button {"outline" if outline else ""}" href="{url}">{text}<span aria-hidden="true">↗</span></a>'
def intro(kicker,title,desc):return f'<section class="page-intro wrap"><p class="kicker">{kicker}</p><h1>{title}</h1><p class="lede">{desc}</p></section>'
def cta(title='Let’s talk about your next outfit.',desc='Your occasion, your inspiration, your own kind of beautiful.',url='/contact/',label='Make an enquiry'):
    return f'<section class="closing wrap"><div><p class="kicker">THE NEXT STEP</p><h2>{title}</h2><p>{desc}</p></div>{btn(label,url)}</section>'
def page(slug,title,body):
    links=''.join(f'<a href="/{s}/" {"aria-current=page" if slug==s else ""}>{t}</a>' for s,t in nav)
    header=f'<div class="topline">GRACEYY FASHION HOUSE & ACADEMY <span>OLOGUNERU, IBADAN</span></div><header><div class="header-inner"><a class="wordmark" href="/" aria-label="GFA home">GFA<span>GRACEYY</span></a><button id="menu" aria-controls="navigation" aria-expanded="false">Menu <span>☰</span></button><nav id="navigation">{links}<a class="navbutton" href="/admissions/">Join the academy ↗</a></nav></div></header>'
    footer='<footer class="wrap"><div class="footer-top"><a class="wordmark" href="/">GFA<span>GRACEYY</span></a><p>For the woman wearing it.<br>For the hands creating it.</p><div><a href="/fashion-house/">Fashion house</a><a href="/academy/">Fashion academy</a><a href="/contact/">Contact & directions</a></div><div><a href="https://www.instagram.com/graceyy_fashion_academy/" target="_blank" rel="noopener">Instagram ↗</a><a href="https://www.tiktok.com/@graceyy_stitchess" target="_blank" rel="noopener">TikTok ↗</a><a href="https://wa.me/2349034699140" target="_blank" rel="noopener">WhatsApp ↗</a></div></div><div class="footer-bottom"><span>© <span data-year></span> Graceyy Fashion House & Academy</span><a href="/privacy/">Privacy</a><a href="/admin/">Staff access</a></div></footer>'
    out=root/slug if slug else root;out.mkdir(parents=True,exist_ok=True)
    (out/'index.html').write_text(f'<!doctype html><html lang="en-NG"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#322327"><title>{escape(title)} | GFA, Ibadan</title><meta name="description" content="Graceyy Fashion House and Academy in Ologuneru, Ibadan. Bridal, asoebi, custom outfits and fashion training."><link rel="stylesheet" href="/style.css"><script src="/config.js" defer></script><script src="/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a>{header}<main id="main">{body}</main>{footer}<a class="chat" href="https://wa.me/2349034699140" target="_blank" rel="noopener" aria-label="Chat with Graceyy on WhatsApp">Let’s chat <span>↗</span></a></body></html>')
