# FORMS
def form(kind):
    academy=kind=='academy'
    options=['Physical training','Online training','Training and accommodation'] if academy else ['Custom outfit','Bridal outfit','Asoebi outfit','General enquiry']
    extra='<label>Your experience<select name="experience"><option value="beginner">I’m a beginner</option><option value="some_experience">I have some sewing experience</option><option value="practising">I already sew professionally</option></select></label><label class="check"><input type="checkbox" name="accommodation"> I’d like information about student accommodation</label>' if academy else ''
    return f'''<form data-enquiry="{kind}"><div class="form-pair"><label>Full name<input name="name" autocomplete="name" minlength="2" maxlength="100" required></label><label>Phone / WhatsApp number<input name="phone" type="tel" autocomplete="tel" pattern="[+0-9 ()-]{{7,24}}" maxlength="24" required placeholder="080… or +234…"></label></div><label>Email <span>(optional)</span><input name="email" type="email" autocomplete="email" maxlength="254"></label><label>{'Training preference' if academy else 'What can we help with?'}<select name="interest">{''.join(f'<option>{o}</option>' for o in options)}</select></label>{extra}<label>{'Preferred start date' if academy else 'Your event date'} <span>(optional)</span><input type="date" name="preferred_date"></label><label>{'What would you like to learn?' if academy else 'Tell us about your outfit or enquiry'}<textarea name="message" minlength="10" maxlength="2000" rows="5" required placeholder="{'Your goals, experience and any questions…' if academy else 'Occasion, style ideas, timing and anything else we should know…'}"></textarea></label><label class="honey" aria-hidden="true">Leave blank<input name="website" tabindex="-1" autocomplete="off"></label><label class="check"><input type="checkbox" name="consent" required> <span>I agree that GFA may use these details to respond to my enquiry. <a href="/privacy/">Privacy notice</a>.</span></label><p class="form-hint">{'This is an admission enquiry, not a confirmed enrolment. No payment is collected here.' if academy else 'Submitting an enquiry does not confirm a booking. Pricing and availability are agreed directly.'}</p><button type="submit" class="button">{'Send my training enquiry' if academy else 'Send my enquiry'} <span>↗</span></button><p class="form-status" role="status" aria-live="polite"></p><a class="whatsapp-fallback" href="https://wa.me/2349034699140" target="_blank" rel="noopener">Prefer WhatsApp? Chat with Graceyy ↗</a></form>'''
body=intro('ADMISSIONS','Your first step<br>starts right here.','Tell us about yourself and the training you’re interested in. The academy can then discuss availability, fees and the next steps with you.')
